        String unicode=base+"/unicode/水星 完全版/%E7%AC%AC01页.png?签名=a%2Fb&name=标题",ascii=Online.checked(unicode).toString();check(ascii.contains("%20")&&ascii.contains("%E7%AC%AC01")&&!ascii.contains("%25E7")&&ascii.equals(Online.checked(ascii).toString()),"Unicode image path and query encode once");check(Online.fetch(s,unicode,Online.LIMIT).length>100,"Unicode image URL reads real image bytes");
        OnlineMemory memory=new OnlineMemory(10);memory.put("a",new byte[8],0);memory.put("b",new byte[8],0);check(memory.used<=10&&memory.get("a")==null,"RAM byte cache evicts to its strict budget");memory.put("large",new byte[11],0);check(memory.get("large")==null,"oversized items never retained");memory.put("ttl",new byte[1],1);Thread.sleep(3);check(memory.get("ttl")==null,"expired chapter metadata is discarded");java.util.concurrent.atomic.AtomicInteger loads=new java.util.concurrent.atomic.AtomicInteger();OnlineMemory coalesced=new OnlineMemory(100);java.util.concurrent.CountDownLatch entered=new java.util.concurrent.CountDownLatch(1),release=new java.util.concurrent.CountDownLatch(1);Runnable run=()->{try{coalesced.load("page",()->{loads.incrementAndGet();entered.countDown();release.await();return new byte[8];});}catch(Exception e){throw new RuntimeException(e);}};Thread one=new Thread(run),two=new Thread(run);one.start();entered.await();two.start();release.countDown();one.join();two.join();check(loads.get()==1,"same-page concurrent requests coalesce");check(OnlineMemory.profile("original",9999999,99999999)[0]==0&&OnlineMemory.profile("low",1,1)[0]==1280&&OnlineMemory.profile("smooth",5*1024*1024,1)[1]==78,"quality presets preserve original and adapt large resources");
        JSONObject md=new JSONObject(s.toString()).put("type","mangadex").put("base_url",base);Online.json(md,base+"/md-original-on");JSONObject mdMeta=new JSONObject().put("book_id","demo").put("chapter",new JSONObject().put("id","chapter-1"));List<String> originalUrls=Online.pages(md,mdMeta),saverUrls=Online.pages(new JSONObject(md.toString()).put("_quality","smooth"),mdMeta);check(originalUrls.get(0).contains("/data/")&&saverUrls.get(0).contains("/data-saver/"),"original and smooth choose distinct upstream quality endpoints");check(Online.fetch(md,originalUrls.get(0),Online.LIMIT)[0]==(byte)0x89,"upstream original page is received without transcoding");Online.json(md,base+"/md-original-off");
        boolean rejected=false;try{Online.normalize(new JSONObject().put("type","script").put("base_url","file:///tmp/x"));}catch(Exception expected){rejected=true;}check(rejected,"unsupported executable source rejected");
        for(String url:new String[]{"file:///tmp/private","https://user:password@example.com"}){rejected=false;try{Online.checked(url);}catch(Exception expected){rejected=true;}check(rejected,"unsafe URL rejected");}
        check(Online.normalize(s).getString("id").equals("fixture"),"source identity remains stable");check(Online.hash("test").equals("9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08"),"cache key SHA256");
        JSONObject jobA=new JSONObject().put("uri","online://A/book/ch1"),jobB=new JSONObject().put("uri","online://B/book/ch1"),newOne=new JSONObject(jobA.toString()).put("_bookTitle","A");JSONArray jobs=OnlineDownloadService.mergeJobs(new JSONArray().put(jobA).put(jobB),new JSONArray().put(newOne));check(jobs.length()==2,"merge download queue deduplicates chapters");check(OnlineDownloadService.scopedJobs(jobs,"online://A/book").length()==1&&OnlineDownloadService.scopedJobs(jobs,"online://B/book").length()==1,"resume scopes by complete book identity");check(OnlineDownloadService.scopedJobs(jobs,"online://A/book2").length()==0,"similar book prefixes cannot cross download scopes");check(jobs.getJSONObject(0).optString("_bookTitle").equals("A"),"queue metadata refreshed without dropping other books");
        for(String type:new String[]{"goda","comicabc","mangakatana"})check(Online.normalize(new JSONObject(s.toString()).put("type",type)).optString("type").equals(type),"new source type accepted: "+type);
        JSONArray decoded=SourceExtra.decodeGoda("J7r092JqAfBaU3wqzOGsM2PqJ3wcwKAnkDAzMqRew3B-BoIKwpR2ynX6xcw3lleW4skRGwrl2R0wCx3GbzmQXInwq5qET9nQ");check(decoded.getJSONObject(0).getString("url").equals("/first.jpg")&&decoded.getJSONObject(1).getString("url").equals("/second.jpg"),"GoDa bounded decoding sorts original page order");for(String invalid:new String[]{"J7rnQ","not-a-list","J7rinvalidnQ"}){boolean bad=false;try{SourceExtra.decodeGoda(invalid);}catch(Exception expected){bad=true;}check(bad,"invalid GoDa list rejected");}
        String record="ac"+"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmn"+"ab"+"am"+"0",big="";for(int i=0;i<24;i++)big+=record;big+="696d67636f6d69632e6a7067";for(int i=0;i<47;i++)big+="x";List<String> comic=SourceExtra.comicImages("var data='"+big+"';for(var i=0;i<24;i++){} var ti=21858; data.length-47-n*6", "1");check(comic.size()==2&&comic.get(0).equals("https://img1.8comic.com/2/21858/1/001_ABC.jpg"),"ComicABC record produces correct CDN path and folder digit");boolean missing=false;try{SourceExtra.comicImages("var data='"+big+"';for(var i=0;i<24;i++){} var ti=21858; data.length-47-n*6","999");}catch(Exception expected){missing=true;}check(missing,"ComicABC missing public chapter rejected");
        List<SourceExtra.A> parsed=SourceExtra.anchors("<div class='cardlist'><a href='/manga/demo'><img data-src='/cover.png'><h3>漫画标题</h3></a></div><a href='/manga/noise'>noise</a>");check(parsed.size()==2&&parsed.get(0).context.contains("cardlist")&&!parsed.get(1).context.contains("cardlist"),"HTML parser isolates catalog context from unrelated links");check(parsed.get(0).headline.toString().equals("漫画标题")&&parsed.get(0).cover.equals("/cover.png"),"HTML title and cover extracted together");
        System.out.println("Java online protocol checks passed: "+count);
